'use strict';
const { test } = require('node:test');
const assert = require('node:assert/strict');
const { runAddon } = require('./helpers/lua');

const FILES = { name: 'Polestar', files: ['Core/Init.lua', 'Core/Compat.lua', 'Theme/Theme.xml', 'QoL/QoL.xml'] };

// Execute just the client commands generated by target macros. Conditions
// refer to the current target at each line; a failed /targetexact keeps it.
// /stopmacro stops only when its conditions match. /tm !n preserves the
// same icon, ~n preserves any icon (Blizzard's SlashCommands.lua).
// The ran hook executes before PostClick, as SecureActionButton_OnClick does,
// so mark cycling observes the unit actually acquired by this press.
const CLIENT = String.raw`
	local B, q = Polestar.QoL.Buttons, stub.qol
	local function set(k, v) Polestar.Set("qol." .. k, v); stub.runTimers() end
	local visible, pings = {}, {}
	local function condition(token)
		if token == "@target" then return true end
		if token == "exists" then return not not q.target end
		if token == "noexists" then return not q.target end
		if token == "dead" then return q.target and q.target.dead end
		if token == "nodead" then return not (q.target and q.target.dead) end
		if token == "harm" then return q.target and q.target.hostile end
		if token == "noharm" then return not (q.target and q.target.hostile) end
		if token == "help" then return q.target and q.target.friend end
		if token == "combat" then return stub.inCombat end
		if token == "nocombat" then return not stub.inCombat end
		error("unmodelled macro condition: " .. token)
	end
	local function options(message)
		local conditional, matches = false, false
		while message:sub(1, 1) == "[" do
			local group, rest = message:match("^%[([^%]]*)%]%s*(.*)$")
			assert(group, "malformed macro condition: " .. message)
			local yes = true
			for token in group:gmatch("[^,]+") do if not condition(token) then yes = false end end
			conditional, matches, message = true, matches or yes, rest
		end
		return not conditional or matches, message
	end
	local function execute(text)
		for line in text:gmatch("[^\n]+") do
			local command, message = line:match("^(%S+)%s*(.*)$")
			assert(command == "/cleartarget" or command == "/targetexact" or command == "/stopmacro"
				or command == "/tm" or command == "/ping", "unmodelled macro command: " .. line)
			local active, value = options(message)
			if active then
				if command == "/cleartarget" then q.target = false
				elseif command == "/targetexact" then q.target = visible[value] or q.target
				elseif command == "/stopmacro" then break
				elseif command == "/ping" and q.target then pings[#pings + 1] = q.target.name
				elseif command == "/tm" and q.target then
					local modifier, icon = value:match("^([!~]?)(%d)$")
					assert(icon, "unmodelled marker: " .. value)
					icon = tonumber(icon)
					local previous = q.target.mark or 0
					if not (modifier == "!" and previous == icon or modifier == "~" and previous ~= 0) then
						q.target.mark = previous == icon and 0 or icon
					end
				end
			end
		end
	end
	setmetatable(q.ran, { __newindex = function(t, i, action)
		assert(action[1] == "macro", "expected a secure macro click")
		execute(action[2]); rawset(t, i, action)
	end })
	local function unit(name, hostile, mark, dead)
		return { name = name, hostile = hostile or false, mark = mark or 0, dead = dead or false }
	end
	local function world(...)
		visible, pings, q.target = {}, {}, false
		for _, u in ipairs({ ... }) do visible[u.name] = u end
	end
	local function click(button)
		local before = #q.ran
		if button == PolestarTargetButton then q.mouseClick(button) else q.keyClick(button) end
		assert(#q.ran == before + 1, "each press must dispatch exactly one macro")
		return { name = q.target and q.target.name or false, mark = q.target and q.target.mark or 0,
			pings = #pings, macro = q.ran[#q.ran][2] }
	end
	local shown = {}
	q.Engine.GetWhileHereList = function() return shown end
	q.Engine.AlongGoal = function(s, g)
		for _, row in ipairs(shown) do if row.step == s and row.index == g then return row end end
	end
	local function setup(npc, mobs)
		shown = {}
		for i, name in ipairs(mobs or { "Skeletal Fiend" }) do
			shown[i] = { t = "kill", subject = name, step = 20 + i, index = 1, status = "active" }
		end
		q.step({ { t = "talk", npcName = npc or "Madame Eva", map = 9000, x = 50, y = 50 } })
	end
	local function rights(kind)
		IsInRaid = function() return kind:find("raid") ~= nil end
		IsInGroup = function() return kind ~= "solo" end
		UnitIsGroupLeader = function() return kind == "party-leader" or kind == "raid-leader" end
		UnitIsGroupAssistant = function() return kind == "raid-assistant" end
		stub.fire("GROUP_ROSTER_UPDATE"); stub.runTimers()
	end
	Polestar.Set("behavior.whileHereStepKey", true)
	set("markTarget", true)
	set("pingTarget", true)
`;

function run(script) {
	return runAddon({ stubs: ['stub_qol.lua'], addons: [FILES], before: 'SLASH_PING1 = "/ping"',
		login: true, script: CLIENT + script }).emitted;
}

function outcome(row) {
	return [row.name, row.mark, row.pings];
}

for (const button of ['PolestarTargetButton', 'PolestarStepButton']) {
	test(`${button}: fallback marks and pings follow the acquired unit, including neutral NPCs`, () => {
		const rows = run(`
			setup()
			world(unit("Skeletal Fiend", true)); emit(click(${button}))
			world(unit("Madame Eva")); emit(click(${button}))
			world(unit("Madame Eva"), unit("Skeletal Fiend", true)); emit(click(${button}))
			world(unit("Madame Eva"), unit("Skeletal Fiend", true)); emit(click(${button}))
		`);
		assert.deepEqual(rows.map(outcome), [
			['Skeletal Fiend', 8, 1], ['Madame Eva', 1, 0],
			['Madame Eva', 1, 0], ['Skeletal Fiend', 8, 1],
		]);
	});

	test(`${button}: dead and absent candidates never receive marks or stop the fallback`, () => {
		const rows = run(`
			setup()
			world(unit("Madame Eva", false, 0, true), unit("Skeletal Fiend", true)); emit(click(${button}))
			world(unit("Skeletal Fiend", true, 0, true), unit("Madame Eva")); emit(click(${button}))
			world(); q.target = unit("Unrelated target", true); emit(click(${button}))
			world(unit("Madame Eva", false, 0, true), unit("Skeletal Fiend", true, 0, true)); emit(click(${button}))
		`);
		assert.deepEqual(rows.map(outcome), [
			['Skeletal Fiend', 8, 1], ['Madame Eva', 1, 0], [false, 0, 0], [false, 0, 0],
		]);
	});

	test(`${button}: custom icons and marks disabled retain each fallback's ping policy`, () => {
		const rows = run(`
			set("markMob", "6"); set("markNpc", "4"); setup()
			world(unit("Skeletal Fiend", true)); emit(click(${button}))
			world(unit("Madame Eva")); emit(click(${button}))
			set("markTarget", false)
			world(unit("Skeletal Fiend", true)); emit(click(${button}))
			world(unit("Madame Eva")); emit(click(${button}))
		`);
		assert.deepEqual(rows.map(outcome), [
			['Skeletal Fiend', 6, 1], ['Madame Eva', 4, 0], ['Skeletal Fiend', 0, 1], ['Madame Eva', 0, 0],
		]);
	});

	test(`${button}: a cycling fallback advances the acquired kind's next icon`, () => {
		const rows = run(`
			set("markMob", "cycle"); setup()
			for i = 1, 3 do world(unit("Skeletal Fiend", true)); emit(click(${button})) end
			set("markMob", "8"); set("markNpc", "cycle")
			for i = 1, 3 do world(unit("Madame Eva")); emit(click(${button})) end
		`);
		assert.deepEqual(rows.map(outcome), [
			['Skeletal Fiend', 2, 1], ['Skeletal Fiend', 3, 1], ['Skeletal Fiend', 4, 1],
			['Madame Eva', 4, 0], ['Madame Eva', 5, 0], ['Madame Eva', 6, 0],
		]);
	});

	test(`${button}: cycling uses the applied name kinds while combat defers a new step`, () => {
		const rows = run(`
			set("markMob", "cycle"); setup()
			q.combat(true)
			q.step({ { t = "kill", target = "Madame Eva" } })
			world(unit("Madame Eva")); emit(click(${button}))
			q.combat(false); stub.runTimers()
			world(unit("Madame Eva", true)); emit(click(${button}))
		`);
		assert.deepEqual(rows.map(outcome), [['Madame Eva', 1, 0], ['Madame Eva', 2, 1]]);
	});

	test(`${button}: a secret target name keeps the applied preferred kind's cycle fallback`, () => {
		const rows = run(`
			set("markNpc", "cycle"); setup()
			local secret, original = {}, UnitName
			issecretvalue = function(v) return v == secret end
			UnitName = function(unit) if unit == "target" then return secret end; return original(unit) end
			world(unit("Skeletal Fiend", true)); emit(click(${button}))
			world(unit("Madame Eva")); emit(click(${button}))
			world(unit("Madame Eva")); emit(click(${button}))
		`);
		assert.deepEqual(rows.map(outcome), [['Skeletal Fiend', 8, 1], ['Madame Eva', 2, 0], ['Madame Eva', 2, 0]]);
	});
}

test('fallbacks honor solo, party, and raid marking rights and preserve existing icons', () => {
	const rows = run(`
		setup()
		for _, group in ipairs({ "solo", "party", "party-leader", "raid", "raid-leader", "raid-assistant" }) do
			rights(group)
			for _, marked in ipairs({ 0, 5 }) do
				world(unit("Skeletal Fiend", true, marked)); emit(click(PolestarTargetButton))
				world(unit("Madame Eva", false, marked)); emit(click(PolestarTargetButton))
			end
		end
	`);
	const expected = [];
	for (const group of ['solo', 'party', 'party-leader', 'raid', 'raid-leader', 'raid-assistant']) {
		for (const marked of [0, 5]) {
			const mob = group === 'raid' ? marked : group === 'party' && marked ? marked : 8;
			const npc = group === 'raid' ? marked : group === 'party' && marked ? marked : 1;
			expected.push(['Skeletal Fiend', mob, group === 'raid' ? 0 : 1], ['Madame Eva', npc, 0]);
		}
	}
	assert.deepEqual(rows.map(outcome), expected);
});

test('mixed macros freeze in combat and apply pending changes after combat', () => {
	const [during, after] = run(`
		setup()
		local t, s = PolestarTargetButton, PolestarStepButton
		local oldT, oldS = t:GetAttribute("macrotext"), s:GetAttribute("macrotext")
		q.combat(true)
		set("markMob", "6"); set("markNpc", "4")
		world(unit("Skeletal Fiend", true)); local a = click(t)
		world(unit("Skeletal Fiend", true)); local b = click(s)
		emit({ a, b, t:GetAttribute("macrotext") == oldT, s:GetAttribute("macrotext") == oldS })
		q.combat(false); stub.runTimers()
		world(unit("Madame Eva")); a = click(t)
		world(unit("Madame Eva")); b = click(s)
		emit({ a, b })
	`);
	assert.deepEqual(during.slice(0, 2).map(outcome), [['Skeletal Fiend', 8, 1], ['Skeletal Fiend', 8, 1]]);
	assert.deepEqual(during.slice(2), [true, true]);
	assert.deepEqual(after.map(outcome), [['Madame Eva', 4, 0], ['Madame Eva', 4, 0]]);
});

test('an NPC-first macro keeps an existing combat target when its NPC is absent', () => {
	const rows = run(`
		setup(); q.combat(true)
		for _, button in ipairs({ PolestarTargetButton, PolestarStepButton }) do
			world(unit("Skeletal Fiend", true)); q.target = unit("Current opponent", true)
			emit(click(button))
		end
	`);
	assert.deepEqual(rows.map(outcome), [['Current opponent', 0, 0], ['Current opponent', 0, 0]]);
});

test('mixed macro truncation keeps complete actions within 255 bytes and rejects unsafe names', () => {
	const rows = run(String.raw`
		local long = string.rep("狼", 24)
		for _, button in ipairs({ PolestarTargetButton, PolestarStepButton }) do
			setup("Madame Eva", { "Skeletal Fiend", long, "Wolf\n/run Unsafe()", "Boar\127" })
			world(unit("Skeletal Fiend", true)); emit(click(button))
			world(unit("Skeletal Fiend", true), unit(long, true)); emit(click(button))
			world(unit(long, true)); emit(click(button))
		end
	`);
	assert.deepEqual(rows.map(outcome), [
		['Skeletal Fiend', 8, 1], ['Skeletal Fiend', 8, 1], ['狼'.repeat(24), 8, 1],
		['Skeletal Fiend', 8, 1], ['Skeletal Fiend', 8, 1], ['狼'.repeat(24), 8, 1],
	]);
	for (const row of rows) {
		assert.ok(Buffer.byteLength(row.macro) <= 255, row.macro);
		assert.doesNotMatch(row.macro, /Unsafe|Boar|\x7f/);
	}
});

test('per-name actions keep their source indices when unsafe names are skipped', () => {
	const [row] = run(String.raw`
		local text = B.TargetMacro({ "Bad\n/run Unsafe()", "Madame Eva", "Skeletal Fiend" }, 1, nil, nil, function(i)
			local kind = i == 3 and "mob" or "npc"
			return B.MarkLine(kind), kind == "mob" and B.QuestPingLine() or nil
		end)
		world(unit("Skeletal Fiend", true)); execute(text)
		emit({ name = q.target and q.target.name, mark = q.target and q.target.mark, pings = #pings, macro = text })
	`);
	assert.deepEqual(outcome(row), ['Skeletal Fiend', 8, 1]);
	assert.ok(Buffer.byteLength(row.macro) <= 255);
	assert.doesNotMatch(row.macro, /Bad|Unsafe/);
});

test('alternating actions stop at the first acquired name across multiple block boundaries', () => {
	const rows = run(`
		set("markTarget", false)
		local names = { "First", "Mob", "Last" }
		for preferred = 1, 3 do
			local text = B.TargetMacro(names, preferred, nil, nil, function(i)
				return nil, i == 2 and B.QuestPingLine() or nil
			end)
			for found = 1, 3 do
				world(unit(names[found], found == 2)); execute(text)
				emit({ name = q.target and q.target.name, mark = q.target and q.target.mark, pings = #pings, macro = text })
			end
			world(unit("First"), unit("Mob", true), unit("Last")); execute(text)
			emit({ name = q.target and q.target.name, mark = q.target and q.target.mark, pings = #pings, macro = text })
		end
	`);
	const expected = [];
	for (const [preferred, ping] of [['First', 0], ['Mob', 1], ['Last', 0]]) {
		expected.push(['First', 0, 0], ['Mob', 0, 1], ['Last', 0, 0], [preferred, 0, ping]);
	}
	assert.deepEqual(rows.map(outcome), expected);
	for (const row of rows) assert.ok(Buffer.byteLength(row.macro) <= 255);
});

test('uniform target macros retain their existing command sequence', () => {
	const rows = run(`
		q.step({ { t = "kill", target = "Wolf" }, { t = "kill", target = "Boar" } })
		for _, button in ipairs({ PolestarTargetButton, PolestarStepButton }) do
			world(unit("Boar", true)); emit(click(button))
		end
	`);
	for (const row of rows) {
		assert.deepEqual(outcome(row), ['Boar', 8, 1]);
		assert.equal(row.macro, '/cleartarget [nocombat]\n/targetexact Wolf\n/cleartarget [dead]\n'
			+ '/targetexact [noexists] Boar\n/cleartarget [dead]\n/ping [@target]\n/tm [@target,harm,nodead] !8');
	}
});
